import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.x7b91k6X.js";const b=JSON.parse('{"title":"漫画 · 第 5 话 Apple 框架：UIKit 与 SwiftUI 双轨","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.05-apple-frameworks.md","filePath":"comics/EP.05-apple-frameworks.md","lastUpdated":1792677465000}'),r={name:"comics/EP.05-apple-frameworks.md"};function l(d,e,c,n,s,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="漫画-·-第-5-话-apple-框架-uikit-与-swiftui-双轨" tabindex="-1">漫画 · 第 5 话 Apple 框架：UIKit 与 SwiftUI 双轨 <a class="header-anchor" href="#漫画-·-第-5-话-apple-框架-uikit-与-swiftui-双轨" aria-label="Permalink to &quot;漫画 · 第 5 话 Apple 框架：UIKit 与 SwiftUI 双轨&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../05-apple-frameworks">05-apple-frameworks.md</a> ｜ 原画：<a href="./EP.05-apple-frameworks.svg">EP.05-apple-frameworks.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：用 UIKit 写页面，改了 model 忘了刷 label，界面状态对不上。</li><li><strong>Runtime 长老</strong>：教她用 SwiftUI 声明式把「同步」这件事交给框架。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>UIKit 是命令式——你一行行告诉视图怎么摆、怎么改，状态变了得手动刷每一处 UI，漏一个就是 bug。SwiftUI 是声明式——你只描述「状态是什么、界面该长什么样」，框架自动 diff 并刷新。两套框架不是二选一，而是双轨共存：新页面用 SwiftUI，老页面留 UIKit，中间靠 <code>UIHostingController</code> 和 <code>UIViewRepresentable</code> 互嵌。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>UIKit 里 <code>label.text = model.title</code>、<code>button.isEnabled = model.canSubmit</code>、<code>tableView.reloadData()</code> 散落在各处。一旦 model 变了但忘了调某行刷新，界面就出现「数据已变、UI 还停在旧状态」的不一致。这就是命令式的代价：状态同步全靠程序员盯，复杂度随视图数量线性增长。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>两套范式的本质区别：</p><ul><li><strong>SwiftUI 声明式</strong>：用 <code>@State</code> / <code>@Observable</code> 标记状态源，视图是状态的纯函数 <code>body = f(state)</code>。状态一变，框架自动重新计算 body、diff 出最小变更、只刷新受影响的视图。</li><li><strong>UIKit 命令式</strong>：直接操作视图对象（addSubview、setTitle、reloadData），你精确控制每一步，但也要对每一步的正确性负责。</li></ul><p>选型不是非此即彼：列表、表单、详情页这类标准界面 SwiftUI 效率最高；自定义绘制、复杂手势、极致性能优化仍用 UIKit + Core Animation。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>双轨共存的三种桥接：</p><ol><li><strong>新页面优先 SwiftUI</strong>：用 <code>@Observable</code> 驱动状态，<code>body</code> 描述界面；</li><li><strong>UIKit 嵌 SwiftUI</strong>：<code>UIHostingController(rootView: MySwiftUIView())</code> 把 SwiftUI 视图塞进 UIKit 流程；</li><li><strong>SwiftUI 嵌 UIKit</strong>：实现 <code>UIViewRepresentable</code> / <code>UIViewControllerRepresentable</code>，把 <code>MKMapView</code>、<code>WKWebView</code> 等 UIKit 控件包装进 SwiftUI。</li></ol><p>企业规范：纯 Swift 新工程以 SwiftUI 为主，遗留工程按页面粒度渐进替换。</p><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>SwiftUI 声明式描述「要什么」，状态驱动 UI 自动刷新，杜绝手动同步遗漏。</li><li>UIKit 仍负责复杂自定义绘制与细粒度性能控制，两套框架长期共存。</li><li>互嵌用 UIHostingController / UIViewRepresentable，新老页面平滑过渡。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：SwiftUI 里 <code>@State</code> 和 <code>@Observable</code> 有什么区别？该选哪个？</p><p><strong>答</strong>：<code>@State</code> 是 SwiftUI 原生的属性包装器，值类型专用，存储由 SwiftUI 框架管理；<code>@Observable</code> 是 iOS 17+ Observation 框架的宏，可用于 class，且只有被视图实际读取的属性变化才触发刷新（精准依赖追踪）。新项目优先 <code>@Observable</code>（iOS 17+），兼容性要求高或值类型局部状态用 <code>@State</code>。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>打开 <code>GuideLab/GuideLab/Labs/</code> 目录，每个 Lab 都是一个 SwiftUI 页面；运行 <code>GuideLab</code> target 体验 SwiftUI 实时预览。再阅读第 5 章关于 <code>UIViewRepresentable</code> 包装 <code>WKWebView</code> 的示例。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>界面跑起来了，可启动要 3 秒、滑动掉帧、Keychain 存的 token 被明文读走。第 6 话《性能与安全：Instruments 与 Keychain》，给 App 做体检和加固。</p>',26)])])}const f=a(r,[["render",l]]);export{b as __pageData,f as default};
